PRINCIPLES = ["不伤害", "诚实", "守权限"]

def check(action):
    for p in PRINCIPLES:
        if violates(p, action):
            return False, "违反：" + p
    return True, "通过"

def violates(principle, action):
    if principle == "不伤害" and "删除" in action:
        return True
    return False

