def internal_market():
    catalog = {}        # 能力 -> 单价
    usage = {}          # 团队 -> 累计花费
    def reg(name, price):
        catalog[name] = price
    def use(team, name):
        cost = catalog.get(name)
        if cost is None:
            return "无此能力"
        usage[team] = usage.get(team, 0.0) + cost
        return f"{team} 调用 {name}，累计 {usage[team]}"
    reg("翻译", 0.005); reg("合规检查", 0.02)
    return use("风控组", "合规检查")

if __name__ == "__main__":
    print(internal_market())

